// Package navidrome forwards Subsonic API traffic to a Navidrome server.
package navidrome

import (
	"encoding/json"
	"encoding/xml"
	"log/slog"
	"net/http"
	"net/http/httputil"
	"net/url"

	"github.com/go-chi/chi/v5/middleware"
)

// subsonicVersion is the API version reported in errors generated by apollo.
const subsonicVersion = "1.16.1"

// unavailableMessage is the client-facing message when Navidrome cannot be reached.
const unavailableMessage = "navidrome is unavailable"

// NewRestProxy returns a RestProxy that forwards requests to upstream using
// transport, or http.DefaultTransport when transport is nil.
func NewRestProxy(upstream *url.URL, transport http.RoundTripper) *RestProxy {
	if transport == nil {
		transport = http.DefaultTransport
	}
	return &RestProxy{proxy: &httputil.ReverseProxy{
		Rewrite: func(r *httputil.ProxyRequest) {
			r.SetURL(upstream)
			r.SetXForwarded()
		},
		Transport: transport,
		// Flush immediately so audio streams and downloads are not buffered.
		FlushInterval: -1,
		ErrorHandler:  writeUnavailable,
	}}
}

func (p *RestProxy) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	p.proxy.ServeHTTP(w, r)
}

// writeUnavailable replies with a Subsonic "failed" envelope, in the format the
// client asked for via the f parameter (JSON, or the XML default).
func writeUnavailable(w http.ResponseWriter, r *http.Request, err error) {
	slog.Error("navidrome unreachable",
		"method", r.Method,
		"path", r.URL.Path,
		"err", err,
		"request_id", middleware.GetReqID(r.Context()),
	)

	if r.URL.Query().Get("f") == "json" {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusBadGateway)
		_ = json.NewEncoder(w).Encode(jsonEnvelope{Response: jsonResponse{
			Status:  "failed",
			Version: subsonicVersion,
			Error:   subsonicError{Code: 0, Message: unavailableMessage},
		}})
		return
	}

	w.Header().Set("Content-Type", "application/xml")
	w.WriteHeader(http.StatusBadGateway)
	_, _ = w.Write([]byte(xml.Header))
	_ = xml.NewEncoder(w).Encode(xmlResponse{
		Xmlns:   "http://subsonic.org/restapi",
		Status:  "failed",
		Version: subsonicVersion,
		Error:   subsonicError{Code: 0, Message: unavailableMessage},
	})
}
